import Foundation

/// Tips (spec §11 TIP-1…TIP-7): what the dialog links to, when Frame Job asks
/// by itself, and what it remembers. Foundation only, so a probe can run the
/// rule against a clock of its own and the AppKit-free export queue can be
/// followed from here. The dialog is `TipsWindowController.swift`, the
/// editor's button `TipsToolbarButton.swift`, Settings' pane
/// `TipsSettingsPane.swift`.

/// The one address "Leave a Tip" opens (TIP-1). The page is the owner's.
enum TipsLink {
    static let url = "https://boppallewyn.com/frame-job/tips/"
}

/// What the schedule is decided from: the stored state, read at one moment.
struct TipsState: Equatable {
    /// When the first counted export succeeded; nil before one has.
    var firstExport: Date?
    /// How many exports a person confirmed in the export card have succeeded.
    var exports = 0
    /// When the automatic ask was last shown, or "Leave a Tip" last pressed.
    var lastAsked: Date?
    /// Settings ▸ Tips' toggle.
    var enabled = true
}

/// When the automatic ask is due (TIP-3). Pure: the state, a moment and a
/// calendar in, a Bool out.
enum TipsSchedule {
    static let firstAskDays = 30
    static let firstAskExports = 5
    static let skipMonths = 6

    /// The Gregorian calendar in the Mac's time zone as it is now, whatever
    /// calendar the person's Mac shows: "December" is its month 12.
    static func localCalendar() -> Calendar {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = TimeZone.current
        return calendar
    }

    /// Off is never due. The first ask waits for `firstAskExports` exports
    /// and `firstAskDays` days since the first of them. After an ask, only a
    /// December is due, and not one whose 1 December 00:00 is less than
    /// `skipMonths` calendar months after the last ask.
    static func isDue(_ state: TipsState, now: Date, calendar: Calendar) -> Bool {
        guard state.enabled else { return false }
        guard let first = state.firstExport else { return false }
        guard state.exports >= firstAskExports else { return false }
        guard now.timeIntervalSince(first) >= Double(firstAskDays) * 86_400 else { return false }
        guard let last = state.lastAsked else { return true }
        guard calendar.component(.month, from: now) == 12 else { return false }
        let year = calendar.component(.year, from: now)
        guard
            let december = calendar.date(from: DateComponents(year: year, month: 12, day: 1)),
            let earliest = calendar.date(byAdding: .month, value: skipMonths, to: last)
        else { return false }
        return earliest <= december
    }
}

/// Settings ▸ Tips' toggle (TIP-5, TIP-6): on shows the editor's Tips button
/// and lets the automatic ask happen.
enum TipsSettings {
    /// Bool; absent = true.
    static let enabledKey = "FrameJobTips"

    /// Posted after the toggle is written, so every editor's Tips button
    /// follows it at once.
    static let didChangeNotification = Notification.Name("FrameJobTipsSettingsDidChange")

    static func isEnabled(in defaults: UserDefaults = .standard) -> Bool {
        defaults.object(forKey: enabledKey) == nil ? true : defaults.bool(forKey: enabledKey)
    }

    /// Writes the toggle and posts `didChangeNotification`.
    static func setEnabled(_ enabled: Bool, in defaults: UserDefaults = .standard) {
        defaults.set(enabled, forKey: enabledKey)
        NotificationCenter.default.post(name: didChangeNotification, object: nil)
    }
}

/// The stored state and its three writers (TIP-5). Every writer is reached
/// only from a person's door: an export confirmed in the export card, or the
/// dialog's "Leave a Tip". Main thread.
final class TipsAsk {
    /// Int; absent = 0.
    static let exportsKey = "FrameJobTipsExports"
    /// A date, stamped by the first counted export and never again.
    static let firstExportKey = "FrameJobTipsFirstExport"
    /// A date: the last automatic ask, or the last press of "Leave a Tip".
    static let lastAskedKey = "FrameJobTipsLastAsked"

    /// The app's own, over the bundle's defaults and the real clock.
    static let shared = TipsAsk()

    private let defaults: UserDefaults
    private let now: () -> Date
    private let calendar: () -> Calendar

    init(
        defaults: UserDefaults = .standard, now: @escaping () -> Date = { Date() },
        calendar: @escaping () -> Calendar = { TipsSchedule.localCalendar() }
    ) {
        self.defaults = defaults
        self.now = now
        self.calendar = calendar
    }

    var state: TipsState {
        TipsState(
            firstExport: defaults.object(forKey: Self.firstExportKey) as? Date,
            exports: defaults.integer(forKey: Self.exportsKey),
            lastAsked: defaults.object(forKey: Self.lastAskedKey) as? Date,
            enabled: TipsSettings.isEnabled(in: defaults))
    }

    /// One more export a person confirmed has succeeded. Counts whatever the
    /// toggle says.
    func countExport() {
        let state = self.state
        defaults.set(state.exports + 1, forKey: Self.exportsKey)
        if state.firstExport == nil { defaults.set(now(), forKey: Self.firstExportKey) }
    }

    /// True when the automatic ask is due now, and then it is recorded as
    /// asked, so the caller shows the dialog and a second call answers false.
    func takeAsk() -> Bool {
        let moment = now()
        guard TipsSchedule.isDue(state, now: moment, calendar: calendar()) else { return false }
        defaults.set(moment, forKey: Self.lastAskedKey)
        return true
    }

    /// "Leave a Tip" was pressed, from any door: that is an ask too.
    func noteTipPageOpened() {
        defaults.set(now(), forKey: Self.lastAskedKey)
    }
}

/// Which export queue jobs a person started (Add to Queue), followed by id as
/// `AgentExports` follows the agent's, so the queue's jobs carry no origin
/// (TIP-4). `settle()` runs on every change of the queue.
final class TipsQueueFollower {
    private let state: (UInt64) -> ExportQueueController.State?
    private let completed: () -> Void
    private(set) var followed: Set<UInt64> = []

    init(state: @escaping (UInt64) -> ExportQueueController.State?, completed: @escaping () -> Void)
    {
        self.state = state
        self.completed = completed
    }

    func follow(_ id: UInt64) {
        followed.insert(id)
        settle()
    }

    /// A followed job that completed calls `completed` once and is dropped;
    /// one cancelled, failed or gone from the list is dropped; one waiting or
    /// running stays.
    func settle() {
        for id in followed.sorted() {
            switch state(id) {
            case .completed:
                followed.remove(id)
                completed()
            case .cancelled, .failed, nil:
                followed.remove(id)
            case .waiting, .running:
                break
            }
        }
    }
}

import AppKit

/// The Tips dialog (spec §11 TIP-1, TIP-2): who a tip funds, "Leave a Tip"
/// and "Not Now".
///
/// **A window and not a sheet, deliberately.** It has three doors — the
/// editor's Tips button, Settings' Tips button and the automatic ask — and
/// two of them have no document to hold a sheet. It is modal to nothing, so
/// no window and no tool call ever waits on it. `SettingsWindowController`'s
/// mould: one instance, not released when closed, no frame autosave name.
/// It is built from the sheets' own pieces so it reads as one of them, and
/// it is left out of the Window menu because both buttons reopen it.
///
/// **Two ways to show it.** `show()` is a person's press: key and front, and
/// it writes nothing. `showAutomatic()` is the ask Frame Job makes by itself
/// (TIP-4): front WITHOUT key, so a Return typed into the editor can never
/// press "Leave a Tip". The two order calls are closures because a probe's
/// window is never key and could not tell the two apart otherwise.
///
/// **What "Leave a Tip" does.** Opens `TipsLink.url` in the browser, records
/// the press as an ask (TIP-5) and closes. Nothing here knows whether anyone
/// tipped.
final class TipsWindowController: NSWindowController {
    /// The app's one Tips dialog. A probe builds its own.
    static let shared = TipsWindowController()

    static let windowTitle = "Tips"
    static let heading = "Frame Job is free and open source"
    static let body =
        "Frame Job is made by one developer. It is free to use and its source is open. If it "
        + "is useful to you, a tip helps pay for the time to keep working on it. Tips are "
        + "voluntary, and nothing in Frame Job is locked without one."
    static let hint = "You can turn this reminder off in Frame Job ▸ Settings… ▸ Tips."
    static let notNowTitle = "Not Now"
    static let tipTitle = "Leave a Tip"

    private let ask: TipsAsk
    private let open: (URL) -> Void
    private let orderKey: (NSWindow) -> Void
    private let orderFront: (NSWindow) -> Void

    private(set) var notNowButton: NSButton!
    private(set) var tipButton: NSButton!

    init(
        ask: TipsAsk = .shared,
        open: @escaping (URL) -> Void = { NSWorkspace.shared.open($0) },
        orderKey: @escaping (NSWindow) -> Void = { $0.makeKeyAndOrderFront(nil) },
        orderFront: @escaping (NSWindow) -> Void = { $0.orderFront(nil) }
    ) {
        self.ask = ask
        self.open = open
        self.orderKey = orderKey
        self.orderFront = orderFront
        let window = NSWindow(
            contentRect: NSRect(x: 0, y: 0, width: sheetWidth, height: 240),
            styleMask: [.titled, .closable], backing: .buffered, defer: false)
        window.title = Self.windowTitle
        window.isReleasedWhenClosed = false
        window.isExcludedFromWindowsMenu = true
        super.init(window: window)
        let content = buildContent()
        window.contentView = content
        window.setContentSize(content.fittingSize)
        window.center()
        applyBackground()
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("TipsWindowController does not support NSCoder")
    }

    private func buildContent() -> NSView {
        let width = sheetWidth - sheetInset * 2
        let bodyLabel = NSTextField(wrappingLabelWithString: Self.body)
        bodyLabel.font = DS.sans(13)
        bodyLabel.textColor = DS.textStrong
        bodyLabel.preferredMaxLayoutWidth = width
        bodyLabel.setAccessibilityIdentifier("tips.body")

        let hintLabel = NSTextField(wrappingLabelWithString: Self.hint)
        hintLabel.font = DS.sans(12)
        hintLabel.textColor = DS.textMuted
        hintLabel.preferredMaxLayoutWidth = width
        hintLabel.setAccessibilityIdentifier("tips.hint")

        notNowButton = StickerButton(
            title: Self.notNowTitle, style: .secondary, target: self,
            action: #selector(notNowClicked(_:)))
        notNowButton.setAccessibilityIdentifier("tips.notnow")
        tipButton = StickerButton(
            title: Self.tipTitle, style: .primary, target: self,
            action: #selector(tipClicked(_:)))
        tipButton.setAccessibilityIdentifier("tips.tip")

        return makeSheetView(
            title: Self.heading, content: sheetColumn([bodyLabel, hintLabel]),
            buttonRow: makeButtonRow(cancel: notNowButton, apply: tipButton))
    }

    private func applyBackground() {
        window?.backgroundColor = DS.chromeBackground
        window?.contentView?.layer?.backgroundColor = DS.chromeBackground.cgColor
    }

    // MARK: - Showing

    /// A person's press of a Tips button: key and front. Writes nothing.
    func show() {
        guard let window else { return }
        applyBackground()
        orderKey(window)
    }

    /// The ask Frame Job makes by itself: front, never key (TIP-4).
    func showAutomatic() {
        guard let window else { return }
        applyBackground()
        orderFront(window)
    }

    // MARK: - Buttons

    @objc func notNowClicked(_ sender: Any?) {
        close()
    }

    @objc func tipClicked(_ sender: Any?) {
        if let url = URL(string: TipsLink.url) { open(url) }
        ask.noteTipPageOpened()
        close()
    }
}

// MARK: - The export doors

/// The two places a person's export reaches Tips (TIP-4): the Export… sheet's
/// success and an Add to Queue job. `EditorViewController+Export.swift` is
/// the only caller; the agent's `export` never comes here. The ask, the
/// dialog and the queue are parameters so a probe runs both doors on its own.
/// Main thread.
final class TipsDoors {
    static let shared = TipsDoors()

    private let ask: TipsAsk
    private let dialog: () -> TipsWindowController
    private let queue: ExportQueueController
    private var follower: TipsQueueFollower?
    private var queueObserver: NSObjectProtocol?
    /// The result sheets still up after a counted success, each waiting for
    /// its window's sheet to end.
    private var sheetEnds: [TipsSheetEnd] = []

    init(
        ask: TipsAsk = .shared,
        dialog: @escaping () -> TipsWindowController = { TipsWindowController.shared },
        queue: ExportQueueController = .shared
    ) {
        self.ask = ask
        self.dialog = dialog
        self.queue = queue
    }

    deinit {
        if let queueObserver { NotificationCenter.default.removeObserver(queueObserver) }
    }

    /// An Export… the person confirmed has succeeded: counted now. The ask
    /// waits until `window`'s sheet — the export's own result panel — ends,
    /// and one main-queue turn more so the sheet has left; with no sheet
    /// attached it is asked at once.
    func exportSucceeded(sheetOn window: NSWindow?) {
        ask.countExport()
        guard let window, window.attachedSheet != nil else {
            askIfDue()
            return
        }
        sheetEnds.append(
            TipsSheetEnd(window: window) { [weak self] watch in
                guard let self else { return }
                self.sheetEnds.removeAll { $0 === watch }
                self.askIfDue()
            })
    }

    /// An Add to Queue job the person confirmed: followed to its end by id.
    /// A completion counts and asks; a cancel or a failure does neither.
    func follow(queueJob id: UInt64) {
        if follower == nil {
            follower = TipsQueueFollower(
                state: { [queue] in queue.job($0)?.state },
                completed: { [weak self] in
                    self?.ask.countExport()
                    self?.askIfDue()
                })
            queueObserver = NotificationCenter.default.addObserver(
                forName: ExportQueueController.didChangeNotification, object: queue, queue: nil
            ) { [weak self] _ in self?.follower?.settle() }
        }
        follower?.follow(id)
    }

    /// Shows the dialog when the schedule says so, recording the ask at the
    /// moment it is shown.
    private func askIfDue() {
        guard ask.takeAsk() else { return }
        dialog().showAutomatic()
    }
}

/// One wait for a window's sheet to end, then one main-queue turn.
private final class TipsSheetEnd: NSObject {
    private let then: (TipsSheetEnd) -> Void

    init(window: NSWindow, then: @escaping (TipsSheetEnd) -> Void) {
        self.then = then
        super.init()
        NotificationCenter.default.addObserver(
            self, selector: #selector(ended(_:)), name: NSWindow.didEndSheetNotification,
            object: window)
    }

    @objc private func ended(_ note: Notification) {
        NotificationCenter.default.removeObserver(self)
        DispatchQueue.main.async { self.then(self) }
    }
}

// MARK: - The command

/// The command half, at the foot of the file that owns the feature
/// (`SettingsWindowController.swift`'s precedent): a nil-target selector, so
/// the editor's Tips button resolves it through the responder chain.
extension AppDelegate {
    @objc func showTips(_ sender: Any?) {
        TipsWindowController.shared.show()
    }
}

