3	/// The agent server's Unix socket (road map 14's MC2, spec §11 MC-1, MC-2,
4	/// MC-6): where it is bound, whether this instance may bind it, the bind,
5	/// its release at quit, and the line Settings' MCP section copies. The
6	/// core's listener (`ReelAgentSocket`) is the app's only one since MC4; it
7	/// serves the prepared catalog through the trampoline, so every call goes
8	/// through `AgentLane.serve`'s one lock (AI-2).
9	///
10	/// **Bound at every launch, and never an alert.** No person asked for it,
11	/// so a launch that cannot bind logs one line, `Frame Job agent socket not
12	/// bound: <reason>`, and carries on; a bound one logs `Frame Job agent socket
13	/// listening at <path>`. Neither line carries the `Frame Job: ` prefix, which
14	/// is the parity check's alone.
15	///
16	/// **The path** (`socketPlan`) is `RC_AGENT_SOCKET` when it is set and not
17	/// empty, else `AppSupport`'s folder plus `Agent/agent.sock`. MC-6 says no
18	/// proof binds the person's socket, so every proof sets `RC_AGENT_SOCKET`.
19	///
20	/// **MC-2's policy** (`socketRefusal`), in order: the folder is made by
21	/// `AppSupport.ensureDirectory` (`0700` at each level it makes) and must
22	/// then be a real folder — not a symlink — owned by this user with no group
23	/// or world bits, because its mode is the socket's whole access control and
24	/// a wrong one is reported, not worked around. A file at the path is asked
25	/// first: a socket that ACCEPTS a connection belongs to another instance and
26	/// is left alone; one that REFUSES is a crash's leftover and is unlinked;
27	/// anything that is not a socket is left alone too (MC-2 sanctions unlinking
28	/// only a refused socket). The core then binds without unlinking anything
29	/// and makes the file `0600`.
30	///
31	/// **The quit** (`unbindSocket`) is a release, not a stop: the core unlinks
32	/// the file only while it is still the one this listener bound (MC1's S7)
33	/// and abandons the listener without a join, so a call in flight that waits
34	/// on main cannot hold the quit. `AgentServer.shared` is the context and
35	/// lives for the process, which the release's contract needs.
36	extension AgentServer {
37	    enum SocketPlan: Equatable {
38	        case bind(path: String)
39	        case skip(reason: String)
40	    }
41	
42	    static let socketEnvironmentKey = "RC_AGENT_SOCKET"
43	
44	    /// The bundle's short version, or "0.0" — what the listener reports as
45	    /// `serverInfo.version`.
46	    static var serverVersion: String {
47	        Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "0.0"
48	    }
49	
50	    /// `~/Library/Application Support/Frame Job/Agent/agent.sock` — the path
51	    /// only; creates nothing.
52	    static var defaultSocketPath: String? {
53	        AppSupport.subdirectory("Agent")?.appendingPathComponent("agent.sock").path
54	    }
55	
56	    /// Where this launch binds, or why it binds nothing. Pure.
57	    static func socketPlan(environment: [String: String], defaultPath: String?) -> SocketPlan {
58	        if let path = environment[socketEnvironmentKey], !path.isEmpty {
59	            return .bind(path: path)
60	        }
61	        guard let defaultPath else { return .skip(reason: "no Application Support folder") }
62	        return .bind(path: defaultPath)
63	    }
64	
65	    /// Binds the socket under MC-2's rules, or logs why not. Main only,
66	    /// from `applicationDidFinishLaunching`; never throws, never alerts.
67	    func bindSocket() {
68	        assert(Thread.isMainThread)
69	        let plan = Self.socketPlan(
70	            environment: ProcessInfo.processInfo.environment, defaultPath: Self.defaultSocketPath)
71	        let path: String
72	        switch plan {
73	        case .skip(let reason):
74	            Self.logSocketNotBound(reason)
75	            return
76	        case .bind(let planned):
77	            path = planned
78	        }
79	        if let reason = Self.socketRefusal(at: path) {
80	            Self.logSocketNotBound(reason)
81	            return
82	        }
83	        do {
84	            let catalog = try prepareCatalog()
85	            try ReelAgentSocket.start(
86	                path: path, serverName: "framejob", version: Self.serverVersion,
87	                toolsJSON: catalog, handler: agentToolTrampoline,
88	                context: Unmanaged.passUnretained(self).toOpaque())
89	        } catch {
90	            Self.logSocketNotBound(error.localizedDescription)
91	            return
92	        }
93	        boundSocketPath = path
94	        NSLog("Frame Job agent socket listening at %@", path)
95	    }
96	
97	    /// The bundled stdio helper (road map 14's MC3), inside this app's own
98	    /// bundle wherever it was launched from.
99	    static var mcpHelperURL: URL {
100	        Bundle.main.bundleURL.appendingPathComponent("Contents/Helpers/framejob-mcp")
101	    }
102	
103	    /// The line Settings' MCP section copies: Claude Code's `mcp add`
104	    /// for the helper at `helperPath`, single-quoted for a POSIX shell.
105	    static func mcpCommand(helperPath: String) -> String {
106	        let quoted = helperPath.replacingOccurrences(of: "'", with: "'\\''")
107	        return "claude mcp add --scope user framejob -- '\(quoted)'"
108	    }
109	
110	    /// For `applicationWillTerminate`: unlinks the socket only if it is
111	    /// still this instance's, with no join. Safe when none is bound.
112	    func unbindSocket() {
113	        ReelAgentSocket.release()
114	    }
115	
116	    private static func logSocketNotBound(_ reason: String) {
117	        NSLog("Frame Job agent socket not bound: %@", reason)
118	    }
119	
120	    /// MC-2 before the bind: the folder made and checked, then whatever is
121	    /// at the path asked and, only when it is a refusing socket, unlinked.
122	    /// Nil means bind; otherwise the reason nothing is bound.
123	    static func socketRefusal(at path: String) -> String? {
124	        let socketURL = URL(fileURLWithPath: path)
125	        let folder = socketURL.deletingLastPathComponent().path
126	        do {
127	            try AppSupport.ensureDirectory(URL(fileURLWithPath: folder, isDirectory: true))
128	        } catch {
129	            return "could not make the folder \(folder): \(error.localizedDescription)"
130	        }
131	
132	        var folderInfo = stat()
133	        guard lstat(folder, &folderInfo) == 0 else {
134	            return "could not read the folder \(folder): \(errnoSentence(errno))"
135	        }
136	        guard folderInfo.st_mode & S_IFMT == S_IFDIR else {
137	            return "\(folder) is not a folder (a symlink is refused)"
138	        }
139	        guard folderInfo.st_uid == getuid() else {
140	            return "\(folder) is owned by uid \(folderInfo.st_uid), not this user (\(getuid()))"
141	        }
142	        if folderInfo.st_mode & 0o077 != 0 { return modeSentence(folder, folderInfo.st_mode) }
143	
144	        var fileInfo = stat()
145	        guard lstat(path, &fileInfo) == 0 else {
146	            let code = errno
147	            return code == ENOENT ? nil : "could not read \(path): \(errnoSentence(code))"
148	        }
149	        guard fileInfo.st_mode & S_IFMT == S_IFSOCK else {
150	            return "\(path) exists and is not a socket; it is left alone"
151	        }
152	        let answer = connectErrno(toSocketAt: path)
153	        if answer == 0 { return "another instance answers at \(path); this one binds none" }
154	        guard answer == ECONNREFUSED else {
155	            return "could not reach the socket at \(path): \(errnoSentence(answer))"
156	        }
157	        guard unlink(path) == 0 || errno == ENOENT else {
158	            return "could not remove the leftover socket \(path): \(errnoSentence(errno))"
159	        }
160	        return nil
161	    }
162	
163	    private static func modeSentence(_ folder: String, _ mode: mode_t) -> String {
164	        let octal = String(format: "%04o", UInt32(mode) & 0o7777)
165	        return "\(folder) is mode \(octal); the socket's folder must be its owner's alone (0700)"
166	    }
167	
168	    private static func errnoSentence(_ code: Int32) -> String {
169	        String(cString: strerror(code))
170	    }
171	
172	    /// `connect(2)` to the socket at `path`: 0 when something accepts,
173	    /// else the errno (ECONNREFUSED for a crash's leftover).
174	    static func connectErrno(toSocketAt path: String) -> Int32 {
175	        let fd = socket(AF_UNIX, SOCK_STREAM, 0)
176	        guard fd >= 0 else { return errno }
177	        defer { close(fd) }
178	        var address = sockaddr_un()
179	        let bytes = Array(path.utf8)
180	        let capacity = MemoryLayout.size(ofValue: address.sun_path)
181	        guard bytes.count < capacity else { return ENAMETOOLONG }
182	        address.sun_family = sa_family_t(AF_UNIX)
183	        address.sun_len = UInt8(MemoryLayout<sockaddr_un>.size)
184	        withUnsafeMutableBytes(of: &address.sun_path) { raw in
185	            raw.copyBytes(from: bytes)
186	        }
187	        let result = withUnsafePointer(to: &address) { pointer in
188	            pointer.withMemoryRebound(to: sockaddr.self, capacity: 1) {
189	                connect(fd, $0, socklen_t(MemoryLayout<sockaddr_un>.size))
190	            }
191	        }
192	        return result == 0 ? 0 : errno
193	    }
194	}
