1	//! The agent server's socket, from the proxy's side: where it is (spec §11
2	//! MC-1, MC-6), whether something answers there, and one HTTP/1.1 POST over
3	//! it. The app's server is `tiny_http` 0.12 (`core/src/agent.rs`), which
4	//! answers a body of 32 768 bytes or more CHUNKED, and a `tools/list` is
5	//! about 240 KB, so the reader decodes both `Content-Length` and chunked
6	//! bodies (and reads to the close when a response has neither).
7	
8	use std::io::{BufRead, BufReader, ErrorKind, Read, Write};
9	use std::os::unix::net::UnixStream;
10	use std::path::{Path, PathBuf};
11	use std::time::Duration;
12	
13	use serde_json::Value;
14	
15	/// Overrides the socket path, for the app and the proxy alike (MC-6).
16	pub const SOCKET_ENV: &str = "RC_AGENT_SOCKET";
17	
18	/// How long a forwarded `tools/list` may wait for the app before the
19	/// snapshot answers instead: the app serves one request at a time, so
20	/// another client's long call holds it.
21	pub const LIST_READ_TIMEOUT: Duration = Duration::from_secs(5);
22	
23	/// The largest response body the reader takes (the app's own request cap).
24	const MAX_BODY_BYTES: usize = 8 * 1024 * 1024;
25	
26	/// `RC_AGENT_SOCKET` when set and not empty, else
27	/// `$HOME/Library/Application Support/Frame Job/Agent/agent.sock` (MC-1).
28	pub fn socket_path() -> Result<PathBuf, String> {
29	    if let Some(path) = std::env::var_os(SOCKET_ENV).filter(|path| !path.is_empty()) {
30	        return Ok(PathBuf::from(path));
31	    }
32	    let home = std::env::var_os("HOME")
33	        .filter(|home| !home.is_empty())
34	        .ok_or_else(|| "HOME is not set, so the agent socket's path is unknown".to_string())?;
35	    Ok(PathBuf::from(home).join("Library/Application Support/Frame Job/Agent/agent.sock"))
36	}
37	
38	/// True when `RC_AGENT_SOCKET` is set and not empty: a scratch instance,
39	/// which a launch tells where to bind (MC-6).
40	pub fn is_scratch() -> bool {
41	    std::env::var_os(SOCKET_ENV).is_some_and(|path| !path.is_empty())
42	}
43	
44	/// What a connect to the socket found.
45	#[derive(Debug, Clone, PartialEq, Eq)]
46	pub enum Reach {
47	    /// Something accepted the connection.
48	    Answers,
49	    /// No file at the path, or a file nothing listens on (a quit's or a
50	    /// crash's leftover): Frame Job is not running there.
51	    Absent,
52	    /// Anything else, in a sentence.
53	    Unreachable(String),
54	}
55	
56	/// Connects to `path` and closes at once.
57	pub fn reach(path: &Path) -> Reach {
58	    match UnixStream::connect(path) {
59	        Ok(_) => Reach::Answers,
60	        Err(error)
61	            if matches!(
62	                error.kind(),
63	                ErrorKind::NotFound | ErrorKind::ConnectionRefused
64	            ) =>
65	        {
66	            Reach::Absent
67	        }
68	        Err(error) => Reach::Unreachable(format!(
69	            "could not connect to Frame Job at {}: {error}",
70	            path.display()
71	        )),
72	    }
73	}
74	
75	/// POSTs `message` to `/mcp` over the socket and reads the answer: 200 →
76	/// its body as JSON, 202 → None (a notification's answer), anything else →
77	/// an error naming the status. `read_timeout` bounds each read (None waits
78	/// as long as the app takes); a read that times out is an error.
79	pub fn post(
80	    path: &Path,
81	    message: &Value,
82	    read_timeout: Option<Duration>,
83	) -> Result<Option<Value>, String> {
84	    let shown = path.display();
85	    let mut stream = UnixStream::connect(path)
86	        .map_err(|e| format!("could not connect to Frame Job at {shown}: {e}"))?;
87	    stream
88	        .set_read_timeout(read_timeout)
89	        .map_err(|e| format!("could not set a read timeout on {shown}: {e}"))?;
90	    let body = serde_json::to_vec(message).map_err(|e| format!("could not encode: {e}"))?;
91	    let head = format!(
92	        "POST /mcp HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\n\
93	         Accept: application/json, text/event-stream\r\nContent-Length: {}\r\n\
94	         Connection: close\r\n\r\n",
95	        body.len()
96	    );
97	    stream
98	        .write_all(head.as_bytes())
99	        .and_then(|()| stream.write_all(&body))
100	        .and_then(|()| stream.flush())
101	        .map_err(|e| format!("could not write to Frame Job at {shown}: {e}"))?;
102	    let mut reader = BufReader::new(stream);
103	    let (status, body) = read_response(&mut reader).map_err(|e| match e.kind() {
104	        ErrorKind::WouldBlock | ErrorKind::TimedOut => format!(
105	            "Frame Job did not answer at {shown} within {} s",
106	            read_timeout.map_or(0, |t| t.as_secs())
107	        ),
108	        _ => format!("could not read Frame Job's answer at {shown}: {e}"),
109	    })?;
110	    match status {
111	        200 => serde_json::from_slice(&body)
112	            .map(Some)
113	            .map_err(|e| format!("Frame Job's answer at {shown} is not JSON: {e}")),
114	        202 => Ok(None),
115	        code => Err(format!("Frame Job answered HTTP {code}")),
116	    }
117	}
118	
119	fn invalid(what: &str) -> std::io::Error {
120	    std::io::Error::new(ErrorKind::InvalidData, what.to_string())
121	}
122	
123	/// One header or chunk-size line, without its CRLF; EOF is an error.
124	fn read_line(reader: &mut impl BufRead) -> std::io::Result<String> {
125	    let mut line = Vec::new();
126	    if reader.read_until(b'\n', &mut line)? == 0 {
127	        return Err(invalid("the connection closed mid-response"));
128	    }
129	    while matches!(line.last(), Some(b'\n' | b'\r')) {
130	        line.pop();
131	    }
132	    String::from_utf8(line).map_err(|_| invalid("a response line is not UTF-8"))
133	}
134	
135	/// The status code and the decoded body of one HTTP/1.1 response.
