144	    let mut chunked = false;
145	    loop {
146	        let line = read_line(reader)?;
147	        if line.is_empty() {
148	            break;
149	        }
150	        let Some((name, value)) = line.split_once(':') else {
151	            continue;
152	        };
153	        let (name, value) = (name.trim(), value.trim());
154	        if name.eq_ignore_ascii_case("content-length") {
155	            length = Some(
156	                value
157	                    .parse::<usize>()
158	                    .map_err(|_| invalid("a bad Content-Length"))?,
159	            );
160	        } else if name.eq_ignore_ascii_case("transfer-encoding") {
161	            chunked = value.to_ascii_lowercase().contains("chunked");
162	        }
163	    }
