187	/// then the zero chunk and any trailer lines up to the blank one.
188	fn read_chunked(reader: &mut impl BufRead) -> std::io::Result<Vec<u8>> {
189	    let mut body = Vec::new();
190	    loop {
191	        let line = read_line(reader)?;
