1	//! Launching Frame Job for a `tools/call` that found no socket (spec §11
2	//! MC-4): its own bundle, in the background (`open -n -g`), at most one
3	//! instance between all the proxies that find no socket at once.
4	//!
5	//! **The lock.** `agent.launch.lock` beside the socket, taken with
6	//! `File::lock` (exclusive, blocking) before the re-check and **held until
7	//! the poll ends**: released before the poll, a second proxy's re-check
8	//! would find nothing answering yet and launch a second instance. A proxy
9	//! that waited on the lock re-checks and finds the first one's instance.
10	//!
11	//! **A scratch socket** (`RC_AGENT_SOCKET` set, MC-6) is passed to the
12	//! instance with `open --env`, with `-ApplePersistenceIgnoreState YES` and
13	//! its stderr written to `framejob-launch.log` beside the socket; the
14	//! person's own socket gets none of these, so their Frame Job opens as theirs.
15	
16	use std::ffi::OsString;
17	use std::fs::{DirBuilder, OpenOptions};
18	use std::os::unix::fs::{DirBuilderExt, OpenOptionsExt};
19	use std::path::Path;
20	use std::process::Command;
21	use std::time::{Duration, Instant};
22	
23	use crate::socket::{self, Reach};
24	
25	/// Overrides the wait for a launched instance, in whole seconds.
26	pub const WAIT_ENV: &str = "RC_MCP_LAUNCH_WAIT";
27	/// MC1's wait: a cold launch measured about a second.
28	pub const DEFAULT_WAIT_SECS: u64 = 60;
29	/// The launch lock's name, beside the socket.
30	pub const LOCK_NAME: &str = "agent.launch.lock";
31	/// A scratch launch's stderr, beside the socket.
32	pub const LAUNCH_LOG_NAME: &str = "framejob-launch.log";
33	/// How every timeout sentence begins (`Session` recognises one by it).
34	pub const TIMEOUT_OPENING: &str = "Frame Job did not answer at ";
35	/// How often the wait asks the socket.
36	const POLL: Duration = Duration::from_millis(50);
37	
38	/// A positive whole number of seconds in `RC_MCP_LAUNCH_WAIT`, else 60 s.
39	pub fn launch_wait() -> Duration {
40	    let seconds = std::env::var(WAIT_ENV)
41	        .ok()
42	        .and_then(|value| value.trim().parse::<u64>().ok())
43	        .filter(|seconds| *seconds > 0)
44	        .unwrap_or(DEFAULT_WAIT_SECS);
45	    Duration::from_secs(seconds)
46	}
47	
48	/// The `/usr/bin/open` arguments that launch `bundle` for `socket`. Pure.
49	pub fn open_arguments(bundle: &Path, socket: &Path, scratch: bool) -> Vec<OsString> {
50	    let mut arguments: Vec<OsString> = vec!["-n".into(), "-g".into()];
51	    if scratch {
52	        let mut env = OsString::from(format!("{}=", socket::SOCKET_ENV));
53	        env.push(socket.as_os_str());
54	        let folder = socket.parent().unwrap_or(Path::new("/"));
55	        arguments.push("--env".into());
56	        arguments.push(env);
57	        arguments.push("--stderr".into());
58	        arguments.push(folder.join(LAUNCH_LOG_NAME).into_os_string());
59	    }
60	    arguments.push(bundle.as_os_str().to_os_string());
61	    if scratch {
62	        arguments.push("--args".into());
63	        arguments.push("-ApplePersistenceIgnoreState".into());
64	        arguments.push("YES".into());
65	    }
66	    arguments
67	}
68	
69	/// The sentence a launch that never bound answers.
70	pub fn timeout_sentence(socket: &Path, wait: Duration, bundle: &Path) -> String {
71	    format!(
72	        "{TIMEOUT_OPENING}{} within {} s of launching {}",
73	        socket.display(),
74	        wait.as_secs(),
75	        bundle.display()
76	    )
77	}
78	
79	/// Whether the socket answered at once or after a launch.
80	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
81	pub enum Launched {
82	    AlreadyUp,
83	    Started,
84	}
85	
86	/// Makes sure something answers at `socket`, launching `bundle` if
87	/// nothing does once the lock is held. The error is a sentence; a launch
88	/// that never answered is `timeout_sentence`'s.
89	pub fn ensure_running(bundle: &Path, socket: &Path) -> Result<Launched, String> {
90	    let folder = socket
91	        .parent()
92	        .ok_or_else(|| format!("the socket path {} has no folder", socket.display()))?;
93	    if !folder.exists() {
94	        DirBuilder::new()
95	            .recursive(true)
96	            .mode(0o700)
97	            .create(folder)
98	            .map_err(|e| format!("could not make {}: {e}", folder.display()))?;
99	    }
100	    let lock_path = folder.join(LOCK_NAME);
101	    let lock = OpenOptions::new()
102	        .read(true)
103	        .write(true)
104	        .create(true)
105	        .truncate(false)
106	        .mode(0o600)
107	        .open(&lock_path)
108	        .map_err(|e| format!("could not open {}: {e}", lock_path.display()))?;
109	    lock.lock()
110	        .map_err(|e| format!("could not lock {}: {e}", lock_path.display()))?;
111	    match socket::reach(socket) {
112	        Reach::Answers => return Ok(Launched::AlreadyUp),
113	        Reach::Unreachable(reason) => return Err(reason),
114	        Reach::Absent => {}
115	    }
116	    let arguments = open_arguments(bundle, socket, socket::is_scratch());
117	    let opened = Command::new("/usr/bin/open")
118	        .args(&arguments)
119	        .output()
120	        .map_err(|e| format!("could not run /usr/bin/open: {e}"))?;
121	    if !opened.status.success() {
122	        return Err(format!(
123	            "/usr/bin/open {} failed ({}): {}",
124	            bundle.display(),
125	            opened.status,
126	            String::from_utf8_lossy(&opened.stderr).trim()
127	        ));
128	    }
129	    let wait = launch_wait();
130	    let started = Instant::now();
131	    loop {
132	        if socket::reach(socket) == Reach::Answers {
133	            drop(lock);
134	            return Ok(Launched::Started);
135	        }
136	        if started.elapsed() >= wait {
137	            drop(lock);
138	            return Err(timeout_sentence(socket, wait, bundle));
139	        }
140	        std::thread::sleep(POLL);
141	    }
142	}
143

