75	/// POSTs `message` to `/mcp` over the socket and reads the answer: 200 →
76	/// its body as JSON, 202 → None (a notification's answer), anything else →
77	/// an error naming the status. `read_timeout` bounds each read (None waits
78	/// as long as the app takes); a read that times out is an error.
79	pub fn post(
80	    path: &Path,
81	    message: &Value,
82	    read_timeout: Option<Duration>,
83	) -> Result<Option<Value>, String> {
84	    let shown = path.display();
85	    let mut stream = UnixStream::connect(path)
86	        .map_err(|e| format!("could not connect to Frame Job at {shown}: {e}"))?;
87	    stream
88	        .set_read_timeout(read_timeout)
89	        .map_err(|e| format!("could not set a read timeout on {shown}: {e}"))?;
90	    let body = serde_json::to_vec(message).map_err(|e| format!("could not encode: {e}"))?;
91	    let head = format!(
92	        "POST /mcp HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\n\
93	         Accept: application/json, text/event-stream\r\nContent-Length: {}\r\n\
94	         Connection: close\r\n\r\n",
95	        body.len()
96	    );
97	    stream
98	        .write_all(head.as_bytes())
99	        .and_then(|()| stream.write_all(&body))
100	        .and_then(|()| stream.flush())
101	        .map_err(|e| format!("could not write to Frame Job at {shown}: {e}"))?;
102	    let mut reader = BufReader::new(stream);
103	    let (status, body) = read_response(&mut reader).map_err(|e| match e.kind() {
104	        ErrorKind::WouldBlock | ErrorKind::TimedOut => format!(
105	            "Frame Job did not answer at {shown} within {} s",
106	            read_timeout.map_or(0, |t| t.as_secs())
107	        ),
108	        _ => format!("could not read Frame Job's answer at {shown}: {e}"),
109	    })?;
110	    match status {
111	        200 => serde_json::from_slice(&body)
112	            .map(Some)
113	            .map_err(|e| format!("Frame Job's answer at {shown} is not JSON: {e}")),
114	        202 => Ok(None),
115	        code => Err(format!("Frame Job answered HTTP {code}")),
116	    }
117	}
118	
119	fn invalid(what: &str) -> std::io::Error {
120	    std::io::Error::new(ErrorKind::InvalidData, what.to_string())
121	}
122	
123	/// One header or chunk-size line, without its CRLF; EOF is an error.
124	fn read_line(reader: &mut impl BufRead) -> std::io::Result<String> {
125	    let mut line = Vec::new();
126	    if reader.read_until(b'\n', &mut line)? == 0 {
127	        return Err(invalid("the connection closed mid-response"));
128	    }
129	    while matches!(line.last(), Some(b'\n' | b'\r')) {
130	        line.pop();
131	    }
132	    String::from_utf8(line).map_err(|_| invalid("a response line is not UTF-8"))
133	}
134	
135	/// The status code and the decoded body of one HTTP/1.1 response.
136	fn read_response(reader: &mut impl BufRead) -> std::io::Result<(u16, Vec<u8>)> {
137	    let status_line = read_line(reader)?;
138	    let status = status_line
139	        .split_whitespace()
140	        .nth(1)
141	        .and_then(|code| code.parse::<u16>().ok())
142	        .ok_or_else(|| invalid("the status line has no code"))?;
143	    let mut length = None;
144	    let mut chunked = false;
145	    loop {
146	        let line = read_line(reader)?;
147	        if line.is_empty() {
148	            break;
149	        }
150	        let Some((name, value)) = line.split_once(':') else {
151	            continue;
152	        };
153	        let (name, value) = (name.trim(), value.trim());
154	        if name.eq_ignore_ascii_case("content-length") {
155	            length = Some(
156	                value
157	                    .parse::<usize>()
158	                    .map_err(|_| invalid("a bad Content-Length"))?,
159	            );
160	        } else if name.eq_ignore_ascii_case("transfer-encoding") {
161	            chunked = value.to_ascii_lowercase().contains("chunked");
162	        }
163	    }
164	    let body = if chunked {
165	        read_chunked(reader)?
166	    } else if let Some(length) = length {
167	        if length > MAX_BODY_BYTES {
168	            return Err(invalid("the answer is over 8 MiB"));
169	        }
170	        let mut body = vec![0; length];
171	        reader.read_exact(&mut body)?;
172	        body
173	    } else {
174	        let mut body = Vec::new();
175	        reader
176	            .take(MAX_BODY_BYTES as u64 + 1)
177	            .read_to_end(&mut body)?;
178	        body
179	    };
180	    if body.len() > MAX_BODY_BYTES {
181	        return Err(invalid("the answer is over 8 MiB"));
182	    }
183	    Ok((status, body))
184	}
185	
186	/// A chunked body: hex sizes (extensions ignored), each chunk and its CRLF,
187	/// then the zero chunk and any trailer lines up to the blank one.
188	fn read_chunked(reader: &mut impl BufRead) -> std::io::Result<Vec<u8>> {
189	    let mut body = Vec::new();
190	    loop {
191	        let line = read_line(reader)?;
192	        let size = line.split(';').next().unwrap_or("").trim();
193	        let size = usize::from_str_radix(size, 16).map_err(|_| invalid("a bad chunk size"))?;
194	        if size == 0 {
195	            while !read_line(reader)?.is_empty() {}
196	            return Ok(body);
197	        }
198	        if body
199	            .len()
200	            .checked_add(size)
201	            .is_none_or(|end| end > MAX_BODY_BYTES)
202	        {
203	            return Err(invalid("the answer is over 8 MiB"));
204	        }
205	        let start = body.len();
206	        body.resize(start + size, 0);
207	        reader.read_exact(&mut body[start..])?;
208	        let mut crlf = [0u8; 2];
209	        reader.read_exact(&mut crlf)?;
210	        if &crlf != b"\r\n" {
211	            return Err(invalid("a chunk does not end in CRLF"));
212	        }
213	    }
214	}
